/**
 * Tidepool design tokens.
 *
 * Source: Figma MCP `get_variable_defs` for the Settings screen (node 3:28) and its
 * component nodes (button 3:8, chip 3:16, field 3:21, tag 3:26).
 *
 * The MCP only returns values for the Light mode of the Figma file; no dark-mode
 * values were available from it. The dark-mode color values below are therefore
 * *derived*, not pulled from Figma: same roles/hues as Light, re-tuned for contrast
 * on a dark surface. Swap them for the real Figma dark-mode values if/when the MCP
 * (or the file itself) exposes them.
 *
 * Non-color tokens (spacing, radii, stroke width, type scale) don't vary by mode,
 * so they live once in `:root`.
 */

:root {
  /* Spacing */
  --padding-xs: 4px;
  --padding-s: 8px;
  --padding-m: 12px;
  --gap-s: 4px;

  /* Radii */
  --radii-field: 6px;
  --radii-chip: 16px;
  --radii-button: 8px;

  /* Stroke */
  --stroke-default: 1px;

  /* Typography */
  --font-family-base: "Inter", sans-serif;

  --text-m-size: 14px;
  --text-m-line-height: 20px;
  --text-m-weight: 500;

  --text-s-size: 12px;
  --text-s-line-height: 16px;
  --text-s-weight: 500;
}

/* Light mode (default) — values as returned by the Figma MCP. */
:root,
[data-theme="light"] {
  --surface-page: #ffffff;

  --text-primary: #1b2433;

  --field-border: #7d8799;
  --field-border-error: #c4231b;

  --chip-background: #e8eef9;
  --chip-text: #1b2433;

  --button-background: #1f5fd6;
  --button-background-hover: #1849a8;
  --button-text: #ffffff;
}

/* Dark mode — derived from Light; not sourced from the Figma MCP (see note above). */
@media (prefers-color-scheme: dark) {
  :root {
    --surface-page: #14181f;

    --text-primary: #e7eaf0;

    --field-border: #8a93a6;
    --field-border-error: #e5726b;

    --chip-background: #232c3d;
    --chip-text: #e7eaf0;

    --button-background: #3b74e0;
    --button-background-hover: #5a8ce8;
    --button-text: #ffffff;
  }
}

[data-theme="dark"] {
  --surface-page: #14181f;

  --text-primary: #e7eaf0;

  --field-border: #8a93a6;
  --field-border-error: #e5726b;

  --chip-background: #232c3d;
  --chip-text: #e7eaf0;

  --button-background: #3b74e0;
  --button-background-hover: #5a8ce8;
  --button-text: #ffffff;
}

/**
 * Tidepool design tokens.
 *
 * Sourced from the Figma MCP's `get_variable_defs` output, merged across the
 * Settings screen and its four components (button, chip, field, tag).
 *
 * Light-mode values below are exact matches of what Figma returned.
 *
 * Dark-mode values are NOT provided by the Figma MCP: its design-to-code
 * tools only ever resolve variables against the active mode (Light), and no
 * dark-mode screenshot or variable dump was captured for this file. The
 * `--color-*` values under `[data-theme="dark"]` are therefore estimated
 * from the light palette's hues/contrast relationships, not pulled from
 * Figma. Re-run `get_variable_defs` with the Dark mode active in Figma and
 * replace these before treating them as source of truth.
 */

:root {
  /* Color */
  --surface-page: #ffffff;
  --text-primary: #1b2433;

  --field-border: #7d8799;
  --field-border-error: #c4231b;

  --chip-background: #e8eef9;
  --chip-text: #1b2433;

  --button-background: #1f5fd6;
  --button-background-hover: #1849a8;
  --button-text: #ffffff;

  /* Spacing */
  --padding-xs: 4px;
  --padding-s: 8px;
  --padding-m: 12px;
  --gap-s: 4px;

  /* Radii */
  --radii-field: 6px;
  --radii-chip: 16px;
  --radii-button: 8px;

  /* Stroke */
  --stroke-default: 1px;

  /* Typography */
  --font-family-base: "Inter", sans-serif;
  --font-weight-medium: 500;

  --text-m-size: 14px;
  --text-m-line-height: 20px;
  --text-m-letter-spacing: 0;

  --text-s-size: 12px;
  --text-s-line-height: 16px;
  --text-s-letter-spacing: 0;
}

/* Estimated — see file header. Only color tokens vary by mode. */
[data-theme="dark"] {
  --surface-page: #11141b;
  --text-primary: #f2f4f8;

  --field-border: #909aad;
  --field-border-error: #e5483f;

  --chip-background: #1f2a3d;
  --chip-text: #dbe3f0;

  --button-background: #3b74e0;
  --button-background-hover: #4f86e8;
  --button-text: #ffffff;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --surface-page: #11141b;
    --text-primary: #f2f4f8;

    --field-border: #909aad;
    --field-border-error: #e5483f;

    --chip-background: #1f2a3d;
    --chip-text: #dbe3f0;

    --button-background: #3b74e0;
    --button-background-hover: #4f86e8;
    --button-text: #ffffff;
  }
}

/*
