 * Source: Figma file b0LpOCBsaRgo8lUqbkQNaY (node 3:28, "Settings" and its
 * component instances: button 3:8, chip 3:16, field 3:21, tag 3:26).
 *
 * Figma's MCP only exposes Light-mode variable values, so the Dark-mode
 * color values below are derived from the Light palette (same hues,
 * re-balanced lightness) rather than read from Figma directly. Every
 * dark pairing has been checked against WCAG 2.1 contrast minimums
 * (4.5:1 for text, 3:1 for UI component borders).
 *
 * Theming: Light is the default. Dark applies when the OS prefers dark
 * and no explicit theme is set, or when `data-theme="dark"` is set on
 * the document (e.g. <html data-theme="dark">) for a manual toggle.
 */

:root {
  /* Typography */
  --font-family-base: "Inter", sans-serif;
  --font-weight-medium: 500;
  --letter-spacing-none: 0;
  --text-m-size: 14px;
  --text-m-line-height: 20px;
  --text-s-size: 12px;
  --text-s-line-height: 16px;

  /* Spacing */
  --padding-xs: 4px;
  --padding-s: 8px;
  --padding-m: 12px;
  --gap-s: 4px;

  /* Radii */
  --radii-field: 6px;
  --radii-chip: 16px;
  --radii-button: 8px;

  /* Borders */
  --stroke-default: 1px;

  /* Color - Light (default) */
  --surface-page: #ffffff;
  --text-primary: #1b2433;

  --field-border: #7d8799;
  --field-border-error: #c4231b;

  --chip-background: #e8eef9;
  --chip-text: #1b2433;

  --button-background: #1f5fd6;
  --button-background-hover: #1849a8;
  --button-text: #ffffff;

  /* Tag is still @experimental in Figma: its colors aren't bound to
     variables there yet, only literal fills. Tokenized here so dark
     mode can theme it too. */
  --tag-positive-background: #d6f5e3;
  --tag-positive-text: #136c3a;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --surface-page: #12161f;
    --text-primary: #e8edf5;

    --field-border: #636d7d;
    --field-border-error: #ff6b61;

    --chip-background: #2a3447;
    --chip-text: #e8edf5;

    --button-background: #3a66d8;
    --button-background-hover: #2a4fb0;
    --button-text: #ffffff;

    --tag-positive-background: #163d2a;
    --tag-positive-text: #6ee7a8;
  }
}

[data-theme="dark"] {
  --surface-page: #12161f;
  --text-primary: #e8edf5;

  --field-border: #636d7d;
  --field-border-error: #ff6b61;

  --chip-background: #2a3447;
  --chip-text: #e8edf5;

  --button-background: #3a66d8;
  --button-background-hover: #2a4fb0;
  --button-text: #ffffff;

  --tag-positive-background: #163d2a;
  --tag-positive-text: #6ee7a8;
}

