import "./Chip.css";

/**
 * Chip — a filter people switch on and off.
 *
 * The icon only appears on the "L" size; there is no design for an "M" chip
 * with an icon, so it's omitted there to match the Figma source.
 */
export function Chip({
  label = "Filter",
  icon = false,
  size = "M",
  selected = false,
  className,
  onClick,
  ...rest
}) {
  const showIcon = size === "L" && icon;
  const classes = ["chip", size === "L" ? "chip--l" : "chip--m", className]
    .filter(Boolean)
    .join(" ");

  return (
    <button
      type="button"
      className={classes}
      aria-pressed={selected}
      onClick={onClick}
      {...rest}
    >
      {showIcon && <span className="chip__icon" aria-hidden="true" />}
      <span className="chip__label">{label}</span>
    </button>
  );
}

